arguments.command:
curl -s https://api.linear.app/graphql -H 'Content-Type: application/json' -H 'Authorization: Bearer <TOKEN>' -d '{"query":"{ users(first: 100) { nodes { id name email archivedAt isAssignable teamMemberships { nodes { team { key } } } } } }"}' | python3 -c "
import json,sys
for u in json.load(sys.stdin)['data']['users']['nodes']:
    if 'Jamal' in u['name'] or 'Olga' in u['name']:
        print(u['id'], '|', u['name'], '|', u.get('email'), '| archived:', u.get('archivedAt'), '| assignable:', u.get('isAssignable'), '| teams:', [t['team']['key'] for t in u['teamMemberships']['nodes']])
"

